from jsonb_populate_recordset(null::public.regimen_items, $catalog$[{"id":"gdp.omeprazole","regimen_id":"gdp","drug_id":"omeprazole","role":"supportive","route":"oral","dose_value":20,"dose_unit":"mg_flat","cap_amount":null,"interval_min":null,"anchor_offset_min":null,"days":[1,2,3,4],"administrations_per_day":1,"duration_min":null,"fallback_solvent":null,"fallback_volume_ml":null,"gap_before_min":null,"notes":{"uk":"Захист шлунка в дні дексаметазону (NSSG L.62). eviQ 3788 дози не дає: лише «розглянути H2-блокатор або інгібітор протонної помпи».","en":"Gastric protection on the dexamethasone days (NSSG L.62). eviQ 3788 gives no dose, only 'consider an H2 antagonist or a proton pump inhibitor'."},"dose_options":[],"dose_modifiers":[],"renal_bands":[],"infusion_params_id":null,"block":"ward","sort_order":10},{"id":"gdp.filgrastim","regimen_id":"gdp","drug_id":"filgrastim","role":"supportive","route":"subcutaneous","dose_value":0.5,"dose_unit":"miu_kg","cap_amount":null,"interval_min":null,"anchor_offset_min":null,"days":[9,10,11,12,13,14,15],"administrations_per_day":1,"duration_min":null,"fallback_solvent":null,"fallback_volume_ml":null,"gap_before_min":null,"notes":{"uk":"З дня 9, 7 днів, у циклах без мобілізації стовбурових клітин (NSSG L.62; шлях протокол не називає — п/ш за інструкцією). Пегфілграстим за NSSG не застосовувати. Розбіжність: eviQ 3788 дози й днів не дає і допускає Г-КСФ короткої або тривалої дії.","en":"From day 9 for 7 days in cycles that are not priming for a stem cell harvest (NSSG L.62; the protocol names no route, subcutaneous per the label). NSSG: pegfilgrastim must not be used. Discrepancy: eviQ 3788 gives no dose or days and allows short- or long-acting G-CSF."},"dose_options":[{"dose_value":1,"dose_unit":"miu_kg","cap_amount":null,"notes":{"uk":"Цикл мобілізації стовбурових клітин: з дня 9 до збору (запас на 8 днів)","en":"A stem cell priming cycle: from day 9 until the harvest (an 8-day supply)"},"source":{"name":"NSSG Oxford Haematology, L.62 R-GDP","url":"https://nssg.oxford-haematology.org.uk/lymphoma/documents/lymphoma-chemo-protocols/L-62-r-gdp.pdf","version":"2.1 (11.2025)","checkedOn":"2026-11-19"}}],"dose_modifiers":[],"renal_bands":[],"infusion_params_id":null,"block":"day_support","sort_order":11},{"id":"r-gdp.omeprazole","regimen_id":"r-gdp","drug_id":"omeprazole","role":"supportive","route":"oral","dose_value":20,"dose_unit":"mg_flat","cap_amount":null,"interval_min":null,"anchor_offset_min":null,"days":[1,2,3,4],"administrations_per_day":1,"duration_min":null,"fallback_solvent":null,"fallback_volume_ml":null,"gap_before_min":null,"notes":{"uk":"Захист шлунка в дні дексаметазону (NSSG L.62). eviQ 3788 дози не дає: лише «розглянути H2-блокатор або інгібітор протонної помпи».","en":"Gastric protection on the dexamethasone days (NSSG L.62). eviQ 3788 gives no dose, only 'consider an H2 antagonist or a proton pump inhibitor'."},"dose_options":[],"dose_modifiers":[],"renal_bands":[],"infusion_params_id":null,"block":"ward","sort_order":13},{"id":"r-gdp.filgrastim","regimen_id":"r-gdp","drug_id":"filgrastim","role":"supportive","route":"subcutaneous","dose_value":0.5,"dose_unit":"miu_kg","cap_amount":null,"interval_min":null,"anchor_offset_min":null,"days":[9,10,11,12,13,14,15],"administrations_per_day":1,"duration_min":null,"fallback_solvent":null,"fallback_volume_ml":null,"gap_before_min":null,"notes":{"uk":"З дня 9, 7 днів, у циклах без мобілізації стовбурових клітин (NSSG L.62; шлях протокол не називає — п/ш за інструкцією). Пегфілграстим за NSSG не застосовувати. Розбіжність: eviQ 3788 дози й днів не дає і допускає Г-КСФ короткої або тривалої дії.","en":"From day 9 for 7 days in cycles that are not priming for a stem cell harvest (NSSG L.62; the protocol names no route, subcutaneous per the label). NSSG: pegfilgrastim must not be used. Discrepancy: eviQ 3788 gives no dose or days and allows short- or long-acting G-CSF."},"dose_options":[{"dose_value":1,"dose_unit":"miu_kg","cap_amount":null,"notes":{"uk":"Цикл мобілізації стовбурових клітин: з дня 9 до збору (запас на 8 днів)","en":"A stem cell priming cycle: from day 9 until the harvest (an 8-day supply)"},"source":{"name":"NSSG Oxford Haematology, L.62 R-GDP","url":"https://nssg.oxford-haematology.org.uk/lymphoma/documents/lymphoma-chemo-protocols/L-62-r-gdp.pdf","version":"2.1 (11.2025)","checkedOn":"2026-11-19"}}],"dose_modifiers":[],"renal_bands":[],"infusion_params_id":null,"block":"day_support","sort_order":14},{"id":"begev.prednisolone","regimen_id":"begev","drug_id":"prednisolone","role":"main","route":"oral","dose_value":100,"dose_unit":"mg_flat","cap_amount":null,"interval_min":null,"anchor_offset_min":null,"days":[1,2,3,4],"administrations_per_day":1,"duration_min":null,"fallback_solvent":null,"fallback_volume_ml":null,"gap_before_min":null,"notes":{"uk":"100 мг у дні 1–4 (Santoro 2020). У записі NCT01884441 преднізолону серед втручань немає — лише гемцитабін, вінорельбін і бендамустин.","en":"100 mg on days 1 to 4 (Santoro 2020). The NCT01884441 record lists no prednisolone among its interventions, only gemcitabine, vinorelbine and bendamustine."},"dose_options":[],"dose_modifiers":[],"renal_bands":[],"infusion_params_id":null,"block":"ward","sort_order":0},{"id":"dhap.dexamethasone","regimen_id":"dhap","drug_id":"dexamethasone","role":"main","route":"oral","dose_value":40,"dose_unit":"mg_flat","cap_amount":null,"interval_min":null,"anchor_offset_min":null,"days":[1,2,3,4],"administrations_per_day":1,"duration_min":null,"fallback_solvent":null,"fallback_volume_ml":null,"gap_before_min":null,"notes":{"uk":"40 мг на добу у дні 1–4, перорально або в/в (Velasquez 1988; eviQ 833).","en":"40 mg a day on days 1 to 4, orally or IV (Velasquez 1988; eviQ 833)."},"dose_options":[],"dose_modifiers":[],"renal_bands":[],"infusion_params_id":null,"block":"ward","sort_order":0},{"id":"dhap.cisplatin","regimen_id":"dhap","drug_id":"cisplatin","role":"main","route":"iv_infusion","dose_value":100,"dose_unit":"mg_m2","cap_amount":null,"interval_min":null,"anchor_offset_min":null,"days":[1],"administrations_per_day":1,"duration_min":1440,"fallback_solvent":"sodium_chloride_0_9","fallback_volume_ml":1000,"gap_before_min":null,"notes":{"uk":"100 мг/м² безперервною інфузією за 24 години в день 1 (Velasquez 1988); у 1000 мл 0,9% NaCl (eviQ 833). eviQ: до цисплатину — 1000 мл 0,9% NaCl з магнію сульфатом 10 ммоль за 60 хв, після — 1000 мл 0,9% NaCl за 60 хв. При нейропатії 2 ступеня й вище цисплатин не вводять (eviQ).","en":"100 mg/m² as a continuous 24-hour infusion on day 1 (Velasquez 1988); in 1000 mL 0.9% sodium chloride (eviQ 833). eviQ: before cisplatin 1000 mL 0.9% sodium chloride with 10 mmol magnesium sulphate over 60 minutes, after it 1000 mL 0.9% sodium chloride over 60 minutes. Omit cisplatin with grade 2 or higher neuropathy (eviQ)."},"dose_options":[],"dose_modifiers":[],"renal_bands":[],"infusion_params_id":null,"block":"infusion","sort_order":1},{"id":"dhap.cytarabine","regimen_id":"dhap","drug_id":"cytarabine","role":"main","route":"iv_infusion","dose_value":2000,"dose_unit":"mg_m2","cap_amount":null,"interval_min":720,"anchor_offset_min":null,"days":[2],"administrations_per_day":2,"duration_min":180,"fallback_solvent":"sodium_chloride_0_9","fallback_volume_ml":500,"gap_before_min":null,"notes":{"uk":"2000 мг/м² двічі з інтервалом 12 годин у день 2 (Velasquez 1988); кожна доза в 500 мл 0,9% NaCl за 3 години (eviQ 833). Понад 70 років — 1000 мг/м² (eviQ). Кортикостероїдні очні краплі від першої дози цитарабіну до 72 годин після останньої; препарат і дозу eviQ не називає. Перед кожною дозою — оцінка мозочкових функцій.","en":"2000 mg/m² twice, 12 hours apart, on day 2 (Velasquez 1988); each dose in 500 mL 0.9% sodium chloride over 3 hours (eviQ 833). Over 70 years 1000 mg/m² (eviQ). Corticosteroid eye drops from the first cytarabine dose until 72 hours after the last; eviQ names no drug or dose. Assess cerebellar function before each dose."},"dose_options":[{"dose_value":1000,"dose_unit":"mg_m2","cap_amount":null,"notes":{"uk":"Понад 70 років (eviQ 833)","en":"Over 70 years (eviQ 833)"},"source":{"name":"eviQ: DHAP (дексаметазон, цитарабін, цисплатин), протокол 833, вер. 4 від 20.03.2024","url":"https://www.eviq.org.au/haematology/lymphoma/833-dhap-dexamethasone-cytarabine-cisplatin","version":"вер. 4 від 20.03.2024","checkedOn":"2026-10-10"}}],"dose_modifiers":[],"renal_bands":[],"infusion_params_id":null,"block":"infusion","sort_order":2},{"id":"hd-ara-c.cytarabine","regimen_id":"hd-ara-c","drug_id":"cytarabine","role":"main","route":"iv_infusion","dose_value":1500,"dose_unit":"mg_m2","cap_amount":null,"interval_min":720,"anchor_offset_min":null,"days":[1,3,5],"administrations_per_day":2,"duration_min":180,"fallback_solvent":"sodium_chloride_0_9","fallback_volume_ml":500,"gap_before_min":null,"notes":{"uk":"Двічі на добу з інтервалом 12 годин, у 500 мл 0,9% NaCl за 3 години (6 введень на цикл). У відділенні застосовують 1,5 г/м²; об'єм 500 мл і швидкість 170 мл/год — з макета листа призначень відділення (звірено 2026-11-20).","en":"Twice daily 12 hours apart, in 500 mL 0.9% NaCl over 3 hours (6 doses per cycle). The department uses 1.5 g/m2; the 500 mL bag and the 170 mL/h rate come from the department's prescription-sheet mock-up (checked 2026-11-20)."},"dose_options":[{"dose_value":3000,"dose_unit":"mg_m2","cap_amount":null,"notes":{"uk":"Повна доза протоколу; зниження до 1,5 г/м² рекомендоване з 60 років і за наявності супутніх хвороб","en":"The protocol's full dose; a reduction to 1.5 g/m2 is advised from age 60 and with comorbidity"},"source":{"name":"NSSG Oxford ML.4 — повна доза 3 г/м²","url":"https://nssg.oxford-haematology.org.uk/myeloid/protocols/ML-4-cytarabine-ara-c-3g-m2.pdf","checkedOn":"2026-09-19"}}],"dose_modifiers":[],"renal_bands":[],"infusion_params_id":"cytarabine.nacl-500","block":"infusion","sort_order":0}]$catalog$::jsonb)
on conflict (id) do update set regimen_id = excluded.regimen_id, drug_id = excluded.drug_id, role = excluded.role, route = excluded.route, dose_value = excluded.dose_value, dose_unit = excluded.dose_unit, cap_amount = excluded.cap_amount, interval_min = excluded.interval_min, anchor_offset_min = excluded.anchor_offset_min, days = excluded.days, administrations_per_day = excluded.administrations_per_day, duration_min = excluded.duration_min, fallback_solvent = excluded.fallback_solvent, fallback_volume_ml = excluded.fallback_volume_ml, gap_before_min = excluded.gap_before_min, notes = excluded.notes, dose_options = excluded.dose_options, dose_modifiers = excluded.dose_modifiers, renal_bands = excluded.renal_bands, infusion_params_id = excluded.infusion_params_id, block = excluded.block, sort_order = excluded.sort_order;

