insert into public.treatment_nodes (id, disease_id, parent_id, kind, title, description, sort_order, steps)
select id, disease_id, parent_id, kind, title, description, sort_order, steps
from jsonb_populate_recordset(null::public.treatment_nodes, $catalog$[{"id":"follicular-lymphoma.nccn-foll-a","disease_id":"follicular-lymphoma","parent_id":"follicular-lymphoma.nccn","kind":"group","title":{"uk":"FOLL-A: критерії GELF і FLIPI-1","en":"FOLL-A: GELF criteria and FLIPI-1"},"description":{"uk":"Сторінка критеріїв настанови NCCN B-Cell Lymphomas 4.2026. Критерії GELF: ураження 3 і більше вузлових ділянок, кожна 3 см і більше в діаметрі; будь-яке вузлове чи позавузлове утворення 7 см і більше; В-симптоми; спленомегалія; плевральний випіт або асцит; цитопенії (лейкоцити < 1,0 ×10⁹/л і/або тромбоцити < 100 ×10⁹/л); лейкемія (понад 5,0 ×10⁹/л злоякісних клітин). FLIPI-1, по одному балу за чинник: вік ≥60 років; стадія Ann Arbor III–IV; гемоглобін < 12 г/дл; ЛДГ сироватки вище верхньої межі норми; 5 і більше вузлових ділянок за мапою цієї самої сторінки, відмінною від звичайної мапи Ann Arbor. Групи: низький ризик 0–1 чинник, проміжний 2, високий 3 і більше. Примітка настанови: ці критерії можуть бути клінічно корисні, щоб вирішити, коли починати лікування. У цій версії примітку про FLIPI-2 зі сторінки прибрали — його склад і групи ризику див. у розділі «Прогностичні індекси й показання до лікування».","en":"The criteria page of NCCN B-Cell Lymphomas 4.2026. GELF criteria: involvement of 3 or more nodal sites, each 3 cm or more in diameter; any nodal or extranodal mass of 7 cm or more; B symptoms; splenomegaly; pleural effusion or peritoneal ascites; cytopenias (leukocytes below 1.0 x10^9/L and/or platelets below 100 x10^9/L); leukemia (more than 5.0 x10^9/L malignant cells). FLIPI-1, one point per factor: age 60 years or older; Ann Arbor stage III-IV; haemoglobin below 12 g/dL; serum LDH above the upper limit of normal; 5 or more nodal sites counted on the map of that same page, which differs from the conventional Ann Arbor map. Groups: low risk 0-1 factors, intermediate 2, high 3 or more. A footnote of the guideline: these criteria may be clinically useful to guide the initiation of treatment. In this version the FLIPI-2 footnote was removed from the page - for its factors and risk groups see the section \"Prognostic indices and indications for treatment\"."},"sort_order":0,"steps":[]},{"id":"follicular-lymphoma.prognosis","disease_id":"follicular-lymphoma","parent_id":null,"kind":"group","title":{"uk":"Прогностичні індекси й показання до лікування","en":"Prognostic indices and indications for treatment"},"description":{"uk":"Шкали FLIPI, FLIPI-2 і PRIMA-PI оцінюють прогноз, а не вибирають лікування: так їх подають і NCCN B-Cell Lymphomas 4.2026, і настанова EHA 2026 (Ladetto M та співавт., HemaSphere 2026;10(10):e70507 — наступниця настанови ESMO, Dreyling M та співавт., Ann Oncol 2021;32:298–308). Початок лікування вирішують критерії великого об'єму пухлини й симптоми. Стадіювання — за оновленням Lugano системи Ann Arbor, із зазначенням пухлинної маси понад 10 см; за EHA 2026 PET-КТ чутливіший за КТ (рівень II, A), біопсія кісткового мозку потрібна, щоб підтвердити стадію I/II (II, A), і її можна пропустити при стадії III–IV, якщо немає незрозумілих цитопеній (II, D). У дослідженні GALLIUM перевага обінутузумабу обмежилася хворими проміжного й високого ризику за FLIPI (EHA 2026, рівень I, B).","en":"FLIPI, FLIPI-2 and PRIMA-PI assess prognosis rather than choose treatment, which is how both NCCN B-Cell Lymphomas 4.2026 and the EHA 2026 guideline present them (Ladetto M, et al. HemaSphere 2026;10(10):e70507 - the successor to the ESMO guideline, Dreyling M, et al. Ann Oncol 2021;32:298-308). When treatment starts is decided by tumour-burden criteria and symptoms. Staging follows the Lugano update of the Ann Arbor system, noting bulky disease above 10 cm; per EHA 2026 PET-CT is more sensitive than CT (level II, A), bone marrow biopsy is recommended to confirm stage I/II disease (II, A) and may be omitted in stage III-IV without equivocal cytopenias (II, D). In the GALLIUM trial the benefit of obinutuzumab was limited to patients at intermediate and high FLIPI risk (EHA 2026, level I, B)."},"sort_order":1,"steps":[]},{"id":"follicular-lymphoma.prognosis-flipi","disease_id":"follicular-lymphoma","parent_id":"follicular-lymphoma.prognosis","kind":"group","title":{"uk":"FLIPI (FLIPI-1)","en":"FLIPI (FLIPI-1)"},"description":{"uk":"Джерело: Solal-Céligny P, Roy P, Colombat P та співавт., Blood 2004;104:1258–1265 (4167 хворих 1985–1992 рр., перевірка на 919); та сама шкала на сторінці FOLL-A настанови NCCN B-Cell Lymphomas 4.2026. П'ять несприятливих чинників, по одному балу: вік понад 60 років; стадія Ann Arbor III–IV; гемоглобін < 120 г/л (12 г/дл); понад 4 уражені вузлові ділянки (тобто 5 і більше); ЛДГ сироватки вище верхньої межі норми. Групи ризику: низький — 0–1 чинник (36 % хворих), проміжний — 2 (37 %, відносний ризик 2,3), високий — 3 і більше (27 %, відносний ризик 4,3). Розбіжність: первинна публікація задає вік «понад 60 років», NCCN на FOLL-A — «≥60 років». Кількість вузлових ділянок NCCN рахує за власною мапою на тій самій сторінці, і вона відрізняється від звичайної мапи ділянок Ann Arbor. Шкалу створено до ери ритуксимабу, але, за розбором NCCN, вона зберегла прогностичну силу й за сучасної імунохіміотерапії (National LymphoCare Study: Nooka AK та співавт., Ann Oncol 2013;24:441–448). Межі застосування: примітка NCCN на FOLL-A називає FLIPI-1 і критерії GELF клінічно корисними, щоб вирішити, коли починати лікування, а розбір тієї самої настанови додає, що способом вибору терапії ці шкали поки не стали.","en":"Source: Solal-Celigny P, Roy P, Colombat P, et al. Blood 2004;104:1258-1265 (4167 patients diagnosed 1985-1992, confirmed on 919); the same score is on page FOLL-A of NCCN B-Cell Lymphomas 4.2026. Five adverse factors, one point each: age over 60 years; Ann Arbor stage III-IV; haemoglobin below 120 g/L (12 g/dL); more than 4 involved nodal areas (that is 5 or more); serum LDH above the upper limit of normal. Risk groups: low with 0-1 factors (36% of patients), intermediate with 2 (37%, hazard ratio 2.3), high with 3 or more (27%, hazard ratio 4.3). A discrepancy: the primary publication sets the age factor at over 60 years, NCCN on FOLL-A at 60 years or older. NCCN counts nodal areas on its own map on that page, which differs from the conventional Ann Arbor site map. The score was built before the rituximab era but, per the NCCN discussion, has kept its prognostic value under modern chemoimmunotherapy (National LymphoCare Study: Nooka AK, et al. Ann Oncol 2013;24:441-448). Limits: the NCCN footnote on FOLL-A calls FLIPI-1 and the GELF criteria clinically useful to guide when treatment is started, while the discussion of the same guideline adds that these scores have not been established as a way of selecting treatment."},"sort_order":0,"steps":[]},{"id":"follicular-lymphoma.prognosis-flipi2","disease_id":"follicular-lymphoma","parent_id":"follicular-lymphoma.prognosis","kind":"group","title":{"uk":"FLIPI-2","en":"FLIPI-2"},"description":{"uk":"Джерело: Federico M, Bellei M, Marcheselli L та співавт., J Clin Oncol 2009;27:4555–4562 (проспективне дослідження F2: 1093 зареєстровані, 942 у вибірці, 832 з повними даними; головна кінцева точка — виживаність без прогресування, медіана спостереження 38 місяців). П'ять чинників, по одному балу: β2-мікроглобулін вище верхньої межі норми; найбільший уражений вузол понад 6 см у найдовшому вимірі; ураження кісткового мозку; гемоглобін < 120 г/л (12 г/дл); вік понад 60 років. Межі груп ризику первинна публікація в анотації не дає; настанова EHA 2026 (таблиця 2) подає їх так: низький — 0–1 чинник, проміжний — 2, високий — 3 і більше. Результати первинної публікації: 3-річна виживаність без прогресування 91 %, 69 % і 51 %, 3-річна загальна виживаність 99 %, 96 % і 84 % для низького, проміжного й високого ризику. Розбір NCCN 4.2026 наводить інші, 5-річні числа: виживаність без прогресування 79 %, 51 % і 20 %, а в підгрупі, що отримувала схеми з ритуксимабом, — 98 %, 88 % і 77 %. Для розрахунку потрібні β2-мікроглобулін (NCCN вносить його до аналізів, корисних в окремих випадках, саме з цієї причини) і дані кісткового мозку. У версії NCCN 4.2026 примітку про FLIPI-2 зі сторінки FOLL-A прибрали — там лишився тільки FLIPI-1, а FLIPI-2 згадано лише в тексті розбору.","en":"Source: Federico M, Bellei M, Marcheselli L, et al. J Clin Oncol 2009;27:4555-4562 (the prospective F2 study: 1093 registered, 942 in the study population, 832 with complete data; the primary endpoint was progression-free survival, median follow-up 38 months). Five factors, one point each: beta-2 microglobulin above the upper limit of normal; longest diameter of the largest involved node over 6 cm; bone marrow involvement; haemoglobin below 120 g/L (12 g/dL); age over 60 years. The primary publication's abstract does not give the risk-group thresholds; the EHA 2026 guideline (table 2) gives them as low with 0-1 factors, intermediate with 2, high with 3 or more. Results in the primary publication: 3-year progression-free survival 91%, 69% and 51%, 3-year overall survival 99%, 96% and 84% for low, intermediate and high risk. The NCCN 4.2026 discussion gives different, 5-year figures: progression-free survival 79%, 51% and 20%, and in the subgroup treated with rituximab-containing regimens 98%, 88% and 77%. The score needs beta-2 microglobulin (which is why NCCN lists it among the tests useful in selected cases) and bone marrow data. In NCCN 4.2026 the FLIPI-2 footnote was removed from page FOLL-A, which now carries FLIPI-1 only; FLIPI-2 is mentioned in the discussion text alone."},"sort_order":1,"steps":[]},{"id":"follicular-lymphoma.prognosis-prima-pi","disease_id":"follicular-lymphoma","parent_id":"follicular-lymphoma.prognosis","kind":"group","title":{"uk":"PRIMA-PI","en":"PRIMA-PI"},"description":{"uk":"Джерело: Bachy E та співавт., Blood 2018 («A simplified scoring system in de novo follicular lymphoma treated initially with immunochemotherapy»); навчальна когорта — 1135 хворих дослідження PRIMA, які отримували першу лінію ритуксимаб + хіміотерапія ± підтримка ритуксимабом. Два параметри: β2-мікроглобулін і ураження кісткового мозку. Групи за первинною публікацією: високий ризик — β2-мікроглобулін понад 3 мг/л; низький — β2-мікроглобулін ≤ 3 мг/л без ураження кісткового мозку; проміжний — β2-мікроглобулін ≤ 3 мг/л з ураженням кісткового мозку. 5-річна виживаність без прогресування — 69 %, 55 % і 37 % для низького, проміжного й високого ризику; у перевірочній когорті 479 хворих (FL2000 LYSA та Iowa/Mayo MER) 5-річна виживаність без подій — 77 %, 57 % і 44 %. Розбіжність: настанова EHA 2026 (таблиця 2) подає PRIMA-PI як просту суму двох чинників — 0 балів низький ризик, 1 проміжний, 2 високий. За таким підрахунком хворий із β2-мікроглобуліном понад 3 мг/л без ураження кісткового мозку потрапляє до проміжної групи, а за первинною публікацією він високого ризику. Обидва правила наведені так, як їх подає кожне джерело; ми між ними не обираємо. NCCN 4.2026 PRIMA-PI не називає: у розборі згадано іншу просту модель — лише β2-мікроглобулін і ЛДГ (Press OW та співавт., Clin Cancer Res 2013;19:6624–6632), яка, за NCCN, прогнозує не гірше за FLIPI-1 і FLIPI-2.","en":"Source: Bachy E, et al. Blood 2018 (\"A simplified scoring system in de novo follicular lymphoma treated initially with immunochemotherapy\"); the training cohort was 1135 patients of the PRIMA trial treated first line with rituximab plus chemotherapy with or without rituximab maintenance. Two parameters: beta-2 microglobulin and bone marrow involvement. Groups as the primary publication defines them: high risk with beta-2 microglobulin above 3 mg/L; low risk with beta-2 microglobulin of 3 mg/L or less and no bone marrow involvement; intermediate risk with beta-2 microglobulin of 3 mg/L or less and bone marrow involvement. Five-year progression-free survival was 69%, 55% and 37% for low, intermediate and high risk; in the validation cohort of 479 patients (FL2000 LYSA and Iowa/Mayo MER) 5-year event-free survival was 77%, 57% and 44%. A discrepancy: the EHA 2026 guideline (table 2) presents PRIMA-PI as a plain count of the two factors - 0 points low risk, 1 intermediate, 2 high. By that count a patient with beta-2 microglobulin above 3 mg/L and no bone marrow involvement falls into the intermediate group, whereas the primary publication makes them high risk. Both rules are given as each source states them; we do not choose between them. NCCN 4.2026 does not name PRIMA-PI: its discussion mentions a different simple model built on beta-2 microglobulin and LDH alone (Press OW, et al. Clin Cancer Res 2013;19:6624-6632), which per NCCN predicts outcomes as well as FLIPI-1 and FLIPI-2."},"sort_order":2,"steps":[]},{"id":"follicular-lymphoma.prognosis-m7-flipi","disease_id":"follicular-lymphoma","parent_id":"follicular-lymphoma.prognosis","kind":"group","title":{"uk":"m7-FLIPI і POD24","en":"m7-FLIPI and POD24"},"description":{"uk":"Джерело: Pastore A, Jurinovic V, Kridel R та співавт., Lancet Oncol 2015;16:1111–1122. m7-FLIPI поєднує мутаційний статус семи генів (EZH2, ARID1A, MEF2B, EP300, FOXO1, CREBBP, CARD11), FLIPI і загальний стан за ECOG. Навчальна когорта — 151 біопсія з дослідження GLSG2000 (перша лінія R-CHOP), перевірочна — 107 хворих на R-CVP. Дає дві групи. Високий ризик: 28 % (43 зі 151) у навчальній когорті, 5-річна виживаність без невдачі лікування 38,3 % проти 77,2 % у низькому ризику (відносний ризик 4,14); у перевірочній когорті — 22 % (24 зі 107), 25,0 % проти 68,2 % (відносний ризик 3,58). Порогових балів самої моделі джерела не наводять — її рахують калькулятором. У рутинну практику шкала не входить: NCCN 4.2026 зазначає, що прогностичне значення m7-FLIPI і мутації EZH2 не втрималося в хворих на схемах із бендамустином (аналіз дослідження GALLIUM: Jurinovic V та співавт., Blood 2019) і потребує більших перевірочних досліджень, а настанова EHA 2026 пише, що мутаційне профілювання нині не має місця в рутинній практиці. Окремо від шкал: за EHA 2026 раннє прогресування — найчастіше його міряють як POD24, прогресування впродовж 24 місяців — найважливіший прогностичний чинник, коли вирішують про повторне лікування, і раннє прогресування після імунохіміотерапії ведуть як агресивну хворобу.","en":"Source: Pastore A, Jurinovic V, Kridel R, et al. Lancet Oncol 2015;16:1111-1122. m7-FLIPI combines the mutation status of seven genes (EZH2, ARID1A, MEF2B, EP300, FOXO1, CREBBP, CARD11) with FLIPI and ECOG performance status. The training cohort was 151 biopsies from the GLSG2000 trial (first-line R-CHOP), the validation cohort 107 patients on R-CVP. It gives two groups. High risk: 28% (43 of 151) in the training cohort, with 5-year failure-free survival of 38.3% versus 77.2% in the low-risk group (hazard ratio 4.14); in the validation cohort 22% (24 of 107), 25.0% versus 68.2% (hazard ratio 3.58). The sources do not give the model's own score thresholds - it is computed with a calculator. The score is not part of routine practice: NCCN 4.2026 notes that the prognostic value of m7-FLIPI and of the EZH2 mutation was not retained in patients on bendamustine-based regimens (an analysis of the GALLIUM trial: Jurinovic V, et al. Blood 2019) and needs larger validation studies, and the EHA 2026 guideline states that mutational profiling currently has no role in routine practice. Apart from the scores: per EHA 2026 early progression - most often measured as POD24, progression within 24 months - is the most important prognostic factor when retreatment is decided, and early progression after chemoimmunotherapy is managed as aggressive disease."},"sort_order":3,"steps":[]},{"id":"follicular-lymphoma.prognosis-indications","disease_id":"follicular-lymphoma","parent_id":"follicular-lymphoma.prognosis","kind":"group","title":{"uk":"Показання до початку лікування: великий об'єм пухлини","en":"Indications to start treatment: high tumour burden"},"description":{"uk":"Прогностичні індекси самі початку лікування не вирішують — його вирішують критерії об'єму пухлини й симптоми. NCCN B-Cell Lymphomas 4.2026, сторінка FOLL-4 (стадія III–IV), перелічує показання: кандидат у клінічне випробування; симптоми; загроза функції органа; клінічно значуща чи прогресивна цитопенія внаслідок лімфоми; клінічно значуща пухлинна маса; стійке або швидке прогресування. Критерії GELF (NCCN, FOLL-A): ураження 3 і більше вузлових ділянок, кожна 3 см і більше в діаметрі; будь-яке вузлове чи позавузлове утворення 7 см і більше; В-симптоми; спленомегалія; плевральний випіт або асцит; цитопенії (лейкоцити < 1,0 ×10⁹/л і/або тромбоцити < 100 ×10⁹/л); лейкемія (понад 5,0 ×10⁹/л злоякісних клітин). За приміткою NCCN, негайна перша лінія ритуксимабом у хворих, які критеріям GELF не відповідають, загальної виживаності не покращила (Ardeshna K та співавт., Lancet Oncol 2014;15:424–435). Настанова EHA 2026 (таблиця 4) подає свій перелік, «модифікований з критеріїв GELF і British National Lymphoma Investigation»: будь-який вузол чи вузлове утворення 7 см і більше (з приміткою, що розглядали також межі 6 і 10 см); ураження 3 і більше вузлових ділянок, кожна 3 см і більше; симптомна спленомегалія (біль, раннє насичення, цитопенії); компресійні симптоми (обструкція сечоводу, стиснення органа) або болісні вогнища; плевральний випіт чи асцит, пов'язані з лімфомою; цитопенії через інфільтрацію кісткового мозку чи селезінки (гемоглобін < 10 г/дл, тромбоцити < 100 ×10⁹/л); В-симптоми (гарячка понад 38 °C, нічні поти, втрата понад 10 % маси тіла за 6 місяців); швидко прогресивна хвороба (впродовж 3 місяців). Два переліки розходяться, тому наведені обидва: цитопенії NCCN задає через лейкоцити й тромбоцити, EHA — через гемоглобін і тромбоцити й межі лейкоцитів не дає; лейкемічна фаза (понад 5,0 ×10⁹/л злоякісних клітин) є тільки в NCCN; спленомегалія в NCCN будь-яка, в EHA — лише симптомна; компресійні симптоми й болісні вогнища є тільки в EHA; строк швидкого прогресування EHA задає (3 місяці), NCCN пише «стійке або швидке» без строку. Без показань обидві настанови радять активне спостереження: NCCN — категорія 1, з оглядом і аналізами кожні 3–6 місяців; EHA — рівень I, A, з медіаною часу до початку лікування близько 3 років, а ритуксимаб як монотерапію називає альтернативою спостереженню (I, B), яка довшає виживаність без прогресування, але не змінює загальної.","en":"Prognostic indices do not by themselves decide when treatment starts - tumour-burden criteria and symptoms do. NCCN B-Cell Lymphomas 4.2026, page FOLL-4 (stage III-IV), lists the indications: candidate for a clinical trial; symptoms; threatened end-organ function; clinically significant or progressive cytopenia secondary to lymphoma; clinically significant bulky disease; steady or rapid progression. The GELF criteria (NCCN, FOLL-A): involvement of 3 or more nodal sites, each 3 cm or more in diameter; any nodal or extranodal mass of 7 cm or more; B symptoms; splenomegaly; pleural effusion or peritoneal ascites; cytopenias (leukocytes below 1.0 x10^9/L and/or platelets below 100 x10^9/L); leukemia (more than 5.0 x10^9/L malignant cells). Per an NCCN footnote, immediate first-line rituximab in patients not meeting the GELF criteria did not improve overall survival (Ardeshna K, et al. Lancet Oncol 2014;15:424-435). The EHA 2026 guideline (table 4) gives its own list, \"modified from GELF and British National Lymphoma Investigation guidelines\": any node or nodal mass of 7 cm or more (with a note that cut-offs of 6 and 10 cm have also been considered); involvement of 3 or more nodal sites, each 3 cm or more; symptomatic splenomegaly (pain, early satiety, cytopenias); compressive symptoms (ureteral obstruction, organ compression) or painful lesions; pleural effusion or ascites attributable to lymphoma; cytopenias from marrow or splenic infiltration (haemoglobin below 10 g/dL, platelets below 100 x10^9/L); B symptoms (fever above 38 C, night sweats, loss of more than 10% of body weight over 6 months); rapidly progressive disease (within 3 months). The two lists differ, so both are given: NCCN defines the cytopenias by leukocytes and platelets, EHA by haemoglobin and platelets with no leukocyte threshold; the leukemic phase (more than 5.0 x10^9/L malignant cells) appears in NCCN only; splenomegaly is any in NCCN and only symptomatic in EHA; compressive symptoms and painful lesions appear in EHA only; EHA puts a time on rapid progression (3 months) while NCCN says \"steady or rapid\" with none. With no indication both guidelines advise active surveillance: NCCN as category 1 with examination and labs every 3-6 months; EHA at level I, A, with a median time to needing treatment of about 3 years, and it names rituximab monotherapy an alternative to surveillance (I, B) that lengthens progression-free survival without changing overall survival."},"sort_order":4,"steps":[]},{"id":"al-amyloidosis.relapsed","disease_id":"al-amyloidosis","parent_id":null,"kind":"line","title":{"uk":"Рецидив або рефрактерність","en":"Relapsed or refractory"},"description":{"uk":"Стандарту немає: схему обирають за попередньою терапією, тривалістю ремісії, токсичністю та побажанням пацієнта. NCCN 1.2027 (AMYL-B 4 з 6) радить розглянути повтор початкової терапії, особливо після кількох років без рецидиву, а тим, хто не отримував даратумумаб, — схему з ним; розглянути збір стовбурових клітин. UpToDate спершу радить аутотрансплантацію при першому рецидиві, якщо її відкладали, та інший клас препаратів, ніж у першій лінії. Спершу йдуть схеми з дозами, далі — картки без розрахунку (NCCN дози для них не наводить). Повний алгоритм — на сторінці шляхів NCCN.","en":"There is no standard: the regimen follows prior therapy, the length of remission, toxicity and the patient's wishes. NCCN 1.2027 (AMYL-B 4 of 6) advises considering a repeat of the initial therapy, especially after several relapse-free years, and a daratumumab-based regimen for those who have not had it; consider stem cell collection. UpToDate first advises autologous transplant at first relapse if it was deferred, and a drug class other than the first line. Regimens with doses come first, then cards without a calculation (NCCN gives no doses for them). The full algorithm is on the NCCN pathways page."},"sort_order":1,"steps":[]},{"id":"aml.induction","disease_id":"aml","parent_id":null,"kind":"line","title":{"uk":"Індукція","en":"Induction"},"description":{"uk":"Інтенсивна індукція для пацієнтів, придатних до неї. Другий курс дають за відновленням показників, а не за календарем; кістковомозкову пункцію роблять після відновлення, перед другим курсом. Орієнтир оцінки за ELN 2022 — CR, CRh або CRi після двох курсів інтенсивної індукції; якщо їх немає, хворобу вважають рефрактерною (ELN 2022, таблиця 8). Після першого курсу «7+3» без відповіді ELN радить розглянути схему з вищими дозами цитарабіну.","en":"Intensive induction for patients fit for it. The second course follows count recovery rather than the calendar; the marrow is sampled after recovery, before that course. The ELN 2022 response landmark is CR, CRh or CRi after two courses of intensive induction; without one the disease counts as refractory (ELN 2022, Table 8). After a first 7+3 course without a response, ELN advises considering a higher-dose cytarabine regimen."},"sort_order":1,"steps":[]},{"id":"aml.consolidation","disease_id":"aml","parent_id":null,"kind":"line","title":{"uk":"Консолідація","en":"Consolidation"},"description":{"uk":"Після досягнення ремісії; вибір залежить від групи ризику й придатності до трансплантації. За ELN 2022 алогенну ТГСК розглядають, коли ймовірність рецидиву без неї очікується понад 35-40%: при сприятливому ризику в першій ремісії її зазвичай не рекомендують, окрім недостатнього очищення від МЗХ, а при несприятливому ризику й у більшості хворих проміжної групи вона рекомендована (ELN 2022, розділ про алогенну ТГСК).","en":"After remission is achieved; the choice depends on the risk group and transplant eligibility. Per ELN 2022, allogeneic HCT is considered when the relapse risk without it is expected to exceed 35-40%: in favourable risk it is generally not recommended in first remission unless MRD clearance is inadequate, while it is recommended in adverse risk and for most patients of the intermediate group (ELN 2022, allogeneic HCT section)."},"sort_order":2,"steps":[]},{"id":"aml.salvage","disease_id":"aml","parent_id":null,"kind":"line","title":{"uk":"Рефрактерність і рецидив","en":"Refractory disease and relapse"},"description":{"uk":"Максимум два курси. Ідарубіцин у другому курсі зважують окремо через кумулятивну дозу антрацикліну. Рецидив за ELN 2022 — бластів у кістковому мозку ≥5%, або поява бластів у крові щонайменше у двох пробах з інтервалом не менше тижня, або позакісткове ураження (ELN 2022, таблиця 8).","en":"Two courses at most. Idarubicin in the second course is weighed separately because of the cumulative anthracycline dose. Relapse per ELN 2022 means 5% or more marrow blasts, or blasts reappearing in the blood in at least two samples at least a week apart, or extramedullary disease (ELN 2022, Table 8)."},"sort_order":3,"steps":[]},{"id":"follicular-lymphoma.nccn-early","disease_id":"follicular-lymphoma","parent_id":"follicular-lymphoma.nccn","kind":"line","title":{"uk":"Стадія I–II (FOLL-3)","en":"Stage I-II (FOLL-3)"},"description":{"uk":"Відповідь оцінюють за Lugano, PET/CT — за 5-бальною шкалою. Спостереження: огляд і аналізи кожні 3–6 міс. 5 років, далі щороку; КТ з контрастом не частіше ніж раз на 6 міс. протягом 2 років після лікування, потім не частіше ніж раз на рік. При прогресії — думати про трансформацію (зростають ЛДГ, одне вогнище росте непропорційно, екстранодальне ураження, нові В-симптоми): PET допомагає обрати місце біопсії; трансформація лікується як ДВКЛ.","en":"Response is judged by Lugano, PET/CT on the 5-point scale. Follow-up: visit and labs every 3-6 months for 5 years, then yearly; contrast CT no more than every 6 months for 2 years after treatment, then no more than yearly. On progression think of transformation (rising LDH, one site growing out of proportion, extranodal disease, new B symptoms): PET helps choose the biopsy site; transformation is treated as DLBCL."},"sort_order":1,"steps":[]},{"id":"follicular-lymphoma.nccn-adv","disease_id":"follicular-lymphoma","parent_id":"follicular-lymphoma.nccn","kind":"line","title":{"uk":"Стадія III–IV (FOLL-4)","en":"Stage III-IV (FOLL-4)"},"description":{"uk":"Показання до лікування: клінічне випробування, симптоми, загроза функції органа, клінічно значуща чи прогресивна цитопенія внаслідок лімфоми, клінічно значуща пухлинна маса, стійке або швидке прогресування (критерії GELF — FOLL-A: ≥3 вузлів по ≥3 см, будь-яке утворення ≥7 см, В-симптоми, спленомегалія, випіт у плевру чи черевну порожнину, лейкоцити <1,0 або тромбоцити <100 ×10⁹/л, лейкемія >5,0 ×10⁹/л). Без показань — активне спостереження (категорія 1) з оглядом кожні 3–6 міс.","en":"Indications for treatment: clinical trial, symptoms, threatened organ function, clinically significant or progressive cytopenia from lymphoma, clinically significant bulk, steady or rapid progression (GELF criteria, FOLL-A: 3 or more nodal sites of 3 cm or more, any mass of 7 cm or more, B symptoms, splenomegaly, pleural or peritoneal effusion, leukocytes below 1.0 or platelets below 100 x10^9/L, leukemia above 5.0 x10^9/L). With no indication — active surveillance (category 1) with visits every 3-6 months."},"sort_order":2,"steps":[]},{"id":"follicular-lymphoma.nccn-1l","disease_id":"follicular-lymphoma","parent_id":"follicular-lymphoma.nccn","kind":"line","title":{"uk":"Перша лінія (FOLL-B 1)","en":"First line (FOLL-B 1)"},"description":{"uk":"Обінутузумаб кращий при рефрактерності до ритуксимабу (прогресія під час або в межах 6 міс. після ритуксимабу). Бендамустин: у дослідженні GALLIUM зросла смертність від опортуністичних інфекцій і вторинних пухлин — профілактика пневмоцистної та VZV-інфекції обов’язкова; перед CAR-T чи CD3×CD20 біспецифічними антитілами — з обережністю (відкласти до лейкафереза). Ритуксимаб при низькому пухлинному навантаженні доречний, якщо стартували зі спостереження або прогресія не відповідає GELF (негайна терапія без GELF загальну виживаність не покращила). Для літніх чи ослаблених, якщо жодна комбінація не буде переносимою, — ритуксимаб 375 мг/м² щотижня ×4. Схеми з обінутузумабом вивчали разом із підтримкою обінутузумабом; застосування без підтримки — екстраполяція даних.","en":"Obinutuzumab is preferred when rituximab-refractory (progression on or within 6 months of rituximab). Bendamustine: in GALLIUM mortality from opportunistic infections and second cancers rose — pneumocystis and VZV prophylaxis is mandatory; use with caution before CAR-T or CD3xCD20 bispecifics (delay until leukapheresis). Rituximab for low tumor burden is appropriate when surveillance was the start or progression does not meet GELF (immediate therapy without GELF did not improve overall survival). For older or infirm patients when no combination is expected to be tolerable — rituximab 375 mg/m2 weekly x4. The obinutuzumab regimens were studied with obinutuzumab maintenance; use without maintenance is an extrapolation of the data."},"sort_order":3,"steps":[]},{"id":"follicular-lymphoma.nccn-resp","disease_id":"follicular-lymphoma","parent_id":"follicular-lymphoma.nccn","kind":"line","title":{"uk":"Відповідь і рецидив (FOLL-5)","en":"Response and relapse (FOLL-5)"},"description":{"uk":"PET-позитивна PR скорочує виживаність без прогресування, але додаткове лікування на цьому етапі результату не змінює. Відсутність відповіді чи прогресія — повторна біопсія (трансформація → як ДВКЛ). Під час спостереження — огляд і аналізи кожні 3–6 міс. 5 років, далі щороку; КТ з контрастом до 2 років не частіше ніж кожні 6 міс., далі не частіше ніж щороку.","en":"A PET-positive PR shortens progression-free survival, but additional treatment at this point has not changed outcome. No response or progression — rebiopsy (transformation → treat as DLBCL). Follow-up: visit and labs every 3-6 months for 5 years, then yearly; contrast CT up to 2 years no more than every 6 months, then no more than yearly."},"sort_order":4,"steps":[]},{"id":"follicular-lymphoma.nccn-2l","disease_id":"follicular-lymphoma","parent_id":"follicular-lymphoma.nccn","kind":"line","title":{"uk":"Друга лінія (FOLL-B 2)","en":"Second line (FOLL-B 2)"},"description":{"uk":"Обінутузумаб кращий для рефрактерних до ритуксимабу. Бендамустин не рекомендований, якщо його вже давали; перед CAR-T чи біспецифічними антитілами — з обережністю. Для ослаблених — ритуксимаб 375 мг/м² щотижня ×4. Перед біспецифічними антитілами CD20×CD3 і CAR-T варто повторною біопсією підтвердити CD20 / CD19.","en":"Obinutuzumab is preferred for rituximab-refractory disease. Bendamustine is not recommended if given before; use with caution before CAR-T or bispecifics. For infirm patients — rituximab 375 mg/m2 weekly x4. Before CD20xCD3 bispecifics and CAR-T consider rebiopsy to confirm CD20 / CD19."},"sort_order":5,"steps":[{"kind":"other","column":"treatment","label":{"uk":"Леналідомід без анти-CD20 — лише якщо анти-CD20 неможливий (окремої схеми в довіднику немає)","en":"Lenalidomide alone — only if an anti-CD20 is not possible (no separate regimen in the catalog)"},"preference":"other","category":null,"notes":null,"target_id":null},{"kind":"page","column":"next","label":{"uk":"Відповідь і рецидив (FOLL-5)","en":"Response and relapse (FOLL-5)"},"preference":null,"category":null,"notes":null,"target_id":"follicular-lymphoma.nccn-resp"}]},{"id":"follicular-lymphoma.nccn-3l","disease_id":"follicular-lymphoma","parent_id":"follicular-lymphoma.nccn","kind":"line","title":{"uk":"Третя лінія й далі (FOLL-B 3)","en":"Third line and later (FOLL-B 3)"},"description":{"uk":"Схеми другої лінії, яких ще не було, теж можливі. Біспецифічні антитіла та CAR-T менш ефективні при CD20-/CD19-негативній пухлині — підтвердити антиген повторною біопсією. Невідомо, чи тафаситамаб або лонкастуксимаб знижують ефективність наступного CD19 CAR-T. Консолідація: алогенна ТГСК у відібраних випадках (невдала мобілізація, стійке ураження кісткового мозку).","en":"Second-line regimens not yet given are also options. Bispecifics and CAR-T work poorly in CD20-/CD19-negative disease — confirm the antigen by rebiopsy. It is unknown whether tafasitamab or loncastuximab lower the efficacy of later CD19 CAR-T. Consolidation: allogeneic HCT in selected cases (mobilization failure, persistent marrow disease)."},"sort_order":6,"steps":[{"kind":"hct","column":"treatment","label":{"uk":"Алогенна ТГСК у відібраних випадках","en":"Allogeneic HCT in selected cases"},"preference":"circumstances","category":null,"notes":null,"target_id":null}]},{"id":"follicular-lymphoma.nccn-ptfl","disease_id":"follicular-lymphoma","parent_id":"follicular-lymphoma.nccn","kind":"line","title":{"uk":"Педіатричний тип ФЛ у дорослих (FOLL-6)","en":"Pediatric-type FL in adults (FOLL-6)"},"description":{"uk":"Локалізована (I–II) пухлина, переважно голова-шия (мигдалики, шийні, підщелепні, привушні вузли) або пах; частіше чоловіки; ІГХ: BCL6, CD10, іноді IRF4/MUM1 (~20%), Ki-67 >30%; перебудов BCL2, BCL6, IRF4/MUM1 немає. Стадія вище II за визначенням — не педіатричний тип. Прогноз відмінний; більшості візуалізація в спостереженні не потрібна, підтримка не показана.","en":"Localized (stage I-II) disease, mostly head and neck (tonsillar, cervical, submandibular, parotid nodes) or inguinal; male predominant; IHC: BCL6, CD10, sometimes IRF4/MUM1 (~20%), Ki-67 above 30%; no BCL2, BCL6 or IRF4/MUM1 rearrangement. Above stage II it is by definition not pediatric-type. Prognosis is excellent; most patients need no surveillance imaging and maintenance is not indicated."},"sort_order":7,"steps":[{"kind":"other","column":"treatment","label":{"uk":"Ексцизія (бажано) або ISRT","en":"Excision (preferred) or ISRT"},"preference":"preferred","category":null,"notes":null,"target_id":null},{"kind":"surveillance","column":"treatment","label":{"uk":"CR — активне спостереження; <CR — рестадіювання PET/CT і далі FOLL-5","en":"CR — active surveillance; <CR — restage with PET/CT, then FOLL-5"},"preference":null,"category":null,"notes":null,"target_id":null},{"kind":"page","column":"next","label":{"uk":"Відповідь і рецидив (FOLL-5)","en":"Response and relapse (FOLL-5)"},"preference":null,"category":null,"notes":null,"target_id":"follicular-lymphoma.nccn-resp"}]},{"id":"follicular-lymphoma.first-line","disease_id":"follicular-lymphoma","parent_id":null,"kind":"line","title":{"uk":"Перша лінія","en":"First line"},"description":{"uk":"Лікування починають за показаннями (критерії GELF); безсимптомну хворобу з малим об'ємом спостерігають.","en":"Treatment starts when there is an indication (GELF criteria); asymptomatic low-burden disease is observed."},"sort_order":2,"steps":[]},{"id":"follicular-lymphoma.second-line","disease_id":"follicular-lymphoma","parent_id":null,"kind":"line","title":{"uk":"Друга лінія","en":"Second line"},"description":{"uk":"Імунохіміотерапія без перехресної резистентності (інша, ніж у першій лінії). При рефрактерності до ритуксимабу перевагу має обінутузумаб. Леналідомід із ритуксимабом — рівноцінний варіант, у довіднику ще без схеми.","en":"Non-cross-resistant immunochemotherapy (different from the first line). Obinutuzumab is preferred in rituximab-refractory disease. Lenalidomide with rituximab is an equal option, not yet a regimen here."},"sort_order":3,"steps":[]},{"id":"follicular-lymphoma.third-line","disease_id":"follicular-lymphoma","parent_id":null,"kind":"line","title":{"uk":"Третя лінія й далі","en":"Third line and beyond"},"description":{"uk":"CAR-T-терапія, біспецифічні антитіла (епкоритамаб, мосунетузумаб, одронекстамаб), занубрутиніб з обінутузумабом, леналідомід із ритуксимабом. У відділенні ці варіанти недоступні; у літніх і ослаблених після тривалих ремісій застосовують ритуксимаб у монорежимі.","en":"CAR-T therapy, bispecific antibodies (epcoritamab, mosunetuzumab, odronextamab), zanubrutinib with obinutuzumab, lenalidomide with rituximab. These are not available in the department; in elderly or frail patients after long remissions rituximab monotherapy is used."},"sort_order":4,"steps":[]},{"id":"follicular-lymphoma.reference","disease_id":"follicular-lymphoma","parent_id":null,"kind":"reference","title":{"uk":"Для ознайомлення (без розрахунку)","en":"For reference (not calculated)"},"description":{"uk":"Курси, про які пишуть джерела, але розклад яких неповний або препарат ще не заведений у довідник: доз для пацієнта тут немає, лише коротка інформація про курс.","en":"Courses the sources describe whose schedule is incomplete or whose drug is not in the catalog yet: no patient doses here, only short facts about the course."},"sort_order":5,"steps":[]}]$catalog$::jsonb)
on conflict (id) do update set disease_id = excluded.disease_id, parent_id = excluded.parent_id, kind = excluded.kind, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, steps = excluded.steps;

insert into public.treatment_node_regimens (id, node_id, regimen_id, notes, sort_order, preference, category)
select id, node_id, regimen_id, notes, sort_order, preference, category
from jsonb_populate_recordset(null::public.treatment_node_regimens, $catalog$[{"id":"al-amyloidosis.relapsed.dara-cybord-cycle-1-2","node_id":"al-amyloidosis.relapsed","regimen_id":"dara-cybord-cycle-1-2","notes":{"uk":"NCCN 1.2027: бортезоміб + циклофосфамід + дексаметазон ± даратумумаб — у списку «повторити початкову терапію» (без рангу); якщо даратумумаб у першій лінії не давали, NCCN радить схему з ним. Розклад — eviQ 4205","en":"NCCN 1.2027: bortezomib, cyclophosphamide and dexamethasone with or without daratumumab — in the \"repeat initial therapy\" list (no rank); if daratumumab was not part of the first line, NCCN advises a regimen with it. The schedule is eviQ 4205"},"sort_order":1,"preference":null,"category":null},{"id":"al-amyloidosis.relapsed.dara-cybord-cycle-3-6","node_id":"al-amyloidosis.relapsed","regimen_id":"dara-cybord-cycle-3-6","notes":null,"sort_order":2,"preference":null,"category":null},{"id":"al-amyloidosis.relapsed.cybord-amyloidosis","node_id":"al-amyloidosis.relapsed","regimen_id":"cybord-amyloidosis","notes":{"uk":"NCCN 1.2027: той самий пункт без даратумумабу; також якщо даратумумаб недоступний","en":"NCCN 1.2027: the same item without daratumumab; also if daratumumab is not available"},"sort_order":3,"preference":null,"category":null},{"id":"al-amyloidosis.relapsed.pom-dex-al","node_id":"al-amyloidosis.relapsed","regimen_id":"pom-dex-al","notes":{"uk":"NCCN 1.2027: помалідомід + дексаметазон ± даратумумаб — у списку «повторити початкову терапію» (без рангу). Дози — лише для схеми без даратумумабу; розклад помалідоміду в дослідженнях різний (дні 1–21 у Sanchorawala 2016, безперервно в Palladini 2017)","en":"NCCN 1.2027: pomalidomide plus dexamethasone with or without daratumumab — in the \"repeat initial therapy\" list (no rank). Doses only for the regimen without daratumumab; the pomalidomide schedule differs between studies (days 1 to 21 in Sanchorawala 2016, continuous in Palladini 2017)"},"sort_order":5,"preference":null,"category"